    question: '什么是冯·诺依曼瓶颈？如何缓解？',
    answer: `## 冯·诺依曼瓶颈

由于CPU与存储器共享一套总线，**取指令和取数据不能同时进行**，导致CPU频繁等待存储器，限制了性能提升。

## 瓶颈成因

1. **结构因素**：程序与数据共用存储器和总线
2. **速度差距**：CPU速度远高于主存（"存储墙"）
3. **串行访问**：必须分时访问指令和数据

## 缓解方法

### 1. 采用哈佛结构
- 指令和数据分开存储与总线
- 取指取数可并行

### 2. 引入Cache
- 用高速缓存缩短访问时间
- 减少CPU等待

### 3. 流水线技术
- 多条指令重叠执行
- 提高部件利用率

### 4. 多体交叉存储
- 多个存储体并行工作
- 提高存储带宽

### 5. RISC简化指令
- 固定长度指令，简化取指
- 寄存器-寄存器操作减少访存

## 现代方案

- 多核并行
- 片上存储器
- 近存计算（处理单元靠近存储器）

> 💡 冯·诺依曼瓶颈是计算机体系结构改进的核心驱动力`,
