    question: '计算机的工作过程是怎样的？',
    answer: `## 计算机工作流程

计算机的工作就是**执行程序**，即不断重复"取指-分析-执行"循环。

## 详细步骤

### 1. 取指令
- PC → MAR → 地址总线 → 主存
- 主存 → 数据总线 → MDR → IR
- PC = PC + 1（指向下一条指令）

### 2. 分析指令
- IR中的操作码 → 译码器
- 产生控制信号，确定操作类型
- 计算操作数有效地址

### 3. 取操作数（如需要）
- 根据寻址方式取得操作数
- 可能访存或读寄存器

### 4. 执行指令
- ALU完成运算
- 结果写回寄存器或主存

### 5. 处理中断（如有）
- 检查中断请求
- 有中断则保存现场、转中断服务

## 示例：执行 a = b + c

1. 取b到累加器ACC
2. 取c到寄存器
3. ALU执行加法
4. 结果写回a的内存单元
5. PC指向下条指令

## 特点

- 周而复始直到遇到停机指令
- 所有指令都经历"取指-执行"过程
- 不同指令执行阶段差异大

> 💡 理解工作流程是学习CPU设计的基础`,
