    answer: `## 登纳德缩放定律

1974年Robert Dennard提出：晶体管尺寸缩小，**功率密度保持恒定**。

## 定律内容

若晶体管尺寸和电压按比例k缩小：
- 尺寸：1/k
- 电压：1/k
- 频率：k（提升）
- 功耗密度：保持不变

## 与摩尔定律关系

| 定律 | 内容 | 现状 |
|------|------|------|
| **摩尔定律** | 晶体管数量翻倍 | 放缓 |
| **登纳德缩放** | 功耗密度恒定 | 失效 |

## 为什么失效？

### 1. 阈值电压不能继续下降
- 低于阈值会产生严重漏电
- 量子隧穿效应明显

### 2. 漏电流增大
- 晶体管尺寸接近原子级
- 静态功耗占比上升

### 3. 工作电压无法继续降低
- 已接近物理下限
- 噪声容限不足

### 4. 频率提升遇阻
- 功耗随频率立方增长
- 散热成为瓶颈

## 影响

1. **主频停滞**：2005年后CPU主频基本不再提升
2. **转向多核**：增加核心数代替提频率
3. **专用化**：GPU、NPU等专用加速
4. **异构计算**：CPU+GPU+FPGA协同

## 暗硅现象

芯片上部分区域因散热限制必须关闭，称为**暗硅（Dark Silicon）**。

> 💡 登纳德缩放失效是多核时代到来的根本原因`,
