    keyword: '异构计算',
    question: '什么是异构计算？有什么优势？',
    answer: `## 异构计算

**异构计算**是指将不同类型的处理器（CPU、GPU、FPGA、ASIC）组合协同工作的计算方式。

## 典型架构

### 1. CPU + GPU
- CPU负责控制逻辑
- GPU负责并行计算
- 通过PCIe或NVLink连接

### 2. CPU + FPGA
- FPGA可重构
- 适合特定算法加速

### 3. CPU + AI芯片
- NPU/TPU加速AI推理
- 高能效比

### 4. SoC集成
- 手机SoC：CPU+GPU+DSP+NPU
- 统一内存空间

## 各类处理器特点

| 处理器 | 优势 | 劣势 |
|--------|------|------|
| CPU | 通用、灵活 | 算力有限 |
| GPU | 并行算力强 | 功耗高 |
| FPGA | 可重构、低延迟 | 开发难 |
| ASIC | 性能功耗最优 | 不可修改 |

## 任务分配原则

- **控制密集**→CPU
- **数据并行**→GPU
- **特定算法**→ASIC/FPGA
- 各尽其能，发挥专长

## 优势

1. **性能提升**：专用硬件加速
2. **能效优化**：合适任务用合适硬件
3. **灵活扩展**：按需配置

## 挑战

1. **编程复杂**：需考虑异构协调
2. **数据搬运**：跨设备传输开销
3. **内存一致性**：多设备数据同步
4. **生态成熟度**：开发工具支持

## 典型平台

- NVIDIA CUDA：CPU+GPU
- Apple Silicon：统一内存架构
- 华为昇腾：CPU+AI Core

> 💡 异构计算是后摩尔时代的性能提升主力`,
