    id: 'q58',
    keyword: '系统评价',
    question: '如何综合评价计算机系统？',
    answer: `## 计算机系统评价

计算机系统性能评价需从**多个维度**综合考量，不能仅看单一指标。

## 评价指标

### 1. 性能指标
- **响应时间**：从提交到完成的时间
- **吞吐率**：单位时间完成的任务数
- **MIPS/FLOPS**：计算能力
- **CPI/IPC**：指令执行效率

### 2. 可靠性
- **MTBF**：平均故障间隔时间
- **MTTR**：平均修复时间
- **可用性** = MTBF / (MTBF + MTTR)

### 3. 能耗
- **性能功耗比**：每瓦性能
- **能效比**：每焦耳完成的计算
- 绿色计算要求

### 4. 成本
- **性能价格比**：性价比
- 包括硬件、软件、维护成本

## 评价方法

### 1. 基准测试
- SPEC、Linpack、TPC
- 客观但可能被"应试"

### 2. 实际应用测试
- 运行真实程序
- 最贴近实际

### 3. 模拟仿真
- 在设计阶段预估性能
- 节省成本

### 4. 监测分析
- 运行时性能计数器
- 找出瓶颈

## 评价原则

1. **公平性**：相同条件对比
2. **全面性**：多指标综合
3. **真实性**：贴近实际应用
4. **可重现**：能重复验证

## 常见误区

- 只看主频→忽略架构
- 只看峰值→忽略持续性能
- 只看单一程序→忽略综合表现

> 💡 最好的评价是"在你关心的应用上跑出最好效果"`,
