    answer: `## 十进制转二进制

整数部分和小数部分采用不同方法。

## 整数部分：除2取余法

**除基取余，逆序排列**

### 示例：将 25 转为二进制

| 除法 | 商 | 余数 |
|------|----|----|
| 25÷2 | 12 | 1 |
| 12÷2 | 6 | 0 |
| 6÷2 | 3 | 0 |
| 3÷2 | 1 | 1 |
| 1÷2 | 0 | 1 |

从下往上读：**11001**

所以 25 = (11001)₂

## 小数部分：乘2取整法

**乘基取整，顺序排列**

### 示例：将 0.625 转为二进制

| 乘法 | 结果 | 整数 |
|------|------|------|
| 0.625×2 | 1.25 | 1 |
| 0.25×2 | 0.5 | 0 |
| 0.5×2 | 1.0 | 1 |

从上往下读：**0.101**

所以 0.625 = (0.101)₂

## 注意事项

1. **整数一定能精确转换**：有限位数
2. **小数可能无限循环**：如0.1无法精确表示
3. **精度受限**：受存储位数限制

## 检验

25 = 16 + 8 + 1 = 2⁴ + 2³ + 2⁰ = 11001 ✓

## 推广

此法适用于十进制转任意进制，只需将2换成r。

> 💡 整数除基取余逆序，小数乘基取整顺序`,
    relatedTopics: ['数制', '数制转换'],
    chapter: '第2章 数据表示与运算',
