    question: '真值和机器数有什么区别？',
    answer: `## 真值与机器数

### 真值
- 符合人类习惯的**带正负号**的数
- 如：+5、-12、+0.25

### 机器数
- 在计算机中**用0/1表示符号**的数
- 符号位：0表示正，1表示负
- 如：00000101、10001100

## 区别

| 项目 | 真值 | 机器数 |
|------|------|--------|
| 符号 | +/− | 0/1 |
| 存储 | 数学表示 | 二进制 |
| 例子 | -5 | 10000101（原码） |

## 机器数的特点

1. **符号数字化**：用0/1代替+/-
2. **小数点位置**：定点数隐含，不占存储
3. **位数固定**：如8位、16位、32位

## 机器数的三种表示

| 表示 | 正数 | 负数 |
|------|------|------|
| **原码** | 符号位0+真值 | 符号位1+真值 |
| **反码** | 同原码 | 符号位1+按位取反 |
| **补码** | 同原码 | 反码+1 |

## 示例（8位）

真值 -5：
- 原码：10000101
- 反码：11111010
- 补码：11111011

## 计算机中的选择

- **整数**：普遍用**补码**
- **浮点数**：尾数用原码或补码，阶码用移码
- **早期机器**：有用原码

## 意义

机器数解决了符号在计算机中的表示问题，是数据表示的基础。

> 💡 真值是给人看的，机器数是给机器存的`,
