    answer: `## Unicode

**Unicode**（统一码）是为每种语言的每个字符设定统一二进制编码的国际标准。

## 基本概念

- 收录全球文字、符号、emoji
- 每个字符有唯一**码点**（Code Point）
- 码点格式：U+XXXX（如"中"= U+4E2D）

## Unicode平面

| 平面 | 范围 | 内容 |
|------|------|------|
| BMP（基本多文种平面） | U+0000~U+FFFF | 常用字符 |
| SMP | U+10000~U+1FFFF | 辅助平面 |
| 其他 | U+20000+ | 扩展汉字等 |

## 编码方式（UTF）

Unicode码点需要编码为字节序列存储：

### UTF-8
- **变长**：1-4字节
- 兼容ASCII（0-127一字节）
- 中文占3字节

| 码点范围 | 字节数 | 格式 |
|---------|--------|------|
| 0-7F | 1 | 0xxxxxxx |
| 80-7FF | 2 | 110xxxxx 10xxxxxx |
| 800-FFFF | 3 | 1110xxxx 10xxxxxx 10xxxxxx |
| 10000+ | 4 | 11110xxx ... |

### UTF-16
- 多数2字节，扩展平面4字节
- Windows内部使用

### UTF-32
- 固定4字节
- 浪费空间，少用

## UTF-8优势

1. **兼容ASCII**：英文文件不变
2. **变长节省空间**：英文1字节，中文3字节
3. **无字节序问题**：网络传输友好
4. **自同步**：出错时能恢复

## 示例

"中"（U+4E2D）的UTF-8编码：
- 码点：4E2D = 0100 1110 0010 1101
- UTF-8：1110 0100 10 111000 10 101101
- 十六进制：E4 B8 AD

## BOM（字节顺序标记）

- U+FEFF
- 用于标识编码和字节序
- UTF-8的BOM：EF BB BF
- 不推荐在UTF-8中使用BOM

## 比较

| 编码 | 字节数（英文/中文） | 优势 |
|------|------------------|------|
| UTF-8 | 1 / 3 | 兼容ASCII、网络友好 |
| UTF-16 | 2 / 2 | Windows支持 |
| UTF-32 | 4 / 4 | 定长，简单 |

## 应用

- **Web**：HTML默认UTF-8
- **数据库**：MySQL utf8mb4支持emoji
- **编程**：Java/C#内部UTF-16

## 注意事项

1. **utf8 vs utf8mb4**：MySQL的utf8是阉割版
2. **emoji**：U+1F600，需4字节UTF-8

> 💡 UTF-8是互联网时代的事实标准，兼容性好`,
