    answer: `## 奇偶校验

**奇偶校验**是最简单的**错误检测码**，通过增加1位校验位使1的个数为奇数或偶数。

## 两种校验

### 奇校验
- 数据+校验位中1的个数为**奇数**
- 示例：数据1010 → 有2个1 → 校验位补1 → 10101（3个1）

### 偶校验
- 数据+校验位中1的个数为**偶数**
- 示例：数据1010 → 有2个1 → 校验位补0 → 10100（2个1）

## 编码示例（偶校验）

| 数据 | 1的个数 | 校验位 | 编码 |
|------|--------|--------|------|
| 1010 | 2（偶） | 0 | 10100 |
| 1011 | 3（奇） | 1 | 10111 |
| 0000 | 0（偶） | 0 | 00000 |

## 检错能力

### 能检测
- **奇数个错误**：1位、3位、5位翻转
- 检测率：50%（仅奇数错误）

### 不能检测
- **偶数个错误**：2位、4位同时翻转
- 无法定位错误位置

## 优缺点

**优点**：
- 实现简单（一个异或门）
- 开销小（仅1位）
- 编码效率高

**缺点**：
- 只能检错，不能纠错
- 漏检率50%（偶数个错误）
- 无法定位错误

## 应用

- **串行通信**：UART奇偶校验位
- **内存校验**：早期内存奇偶校验
- **简单数据传输**

## 改进

- **二维奇偶校验**：行和列都校验，可定位错误
- **海明码**：可检错并纠错

> 💡 奇偶校验是最简单的检错码，适合低错误率场景`,
