    answer: `## 补码乘法

**补码乘法**直接对补码进行乘法运算，符号位参与运算，无需单独处理。

## 与原码乘法对比

| 项目 | 原码乘法 | 补码乘法 |
|------|---------|---------|
| 符号处理 | 单独异或 | 参与运算 |
| 数值部分 | 绝对值 | 补码直接 |
| 算法 | 移位累加 | Booth等算法 |
| 减法 | 不需要 | 可能需要 |
| 复杂度 | 简单 | 较复杂 |

## 校正法

### 基本思路
- 数值部分按原码乘法
- **最后一步校正**：若乘数为负，减去被乘数

### 公式
设[x]补=x0.x1x2...xn，[y]补=y0.y1y2...yn

若y0=0（正数）：直接乘
若y0=1（负数）：结果减去[x]补×2ⁿ

## Booth算法

最常用的补码乘法，**通过乘数相邻位比较**决定操作。

### Booth规则

观察乘数相邻两位yᵢ和yᵢ₋₁（设y₋₁=0）：

| yᵢ | yᵢ₋₁ | 操作 |
|----|------|------|
| 0 | 0 | 部分积右移 |
| 0 | 1 | +[x]补，右移 |
| 1 | 0 | -[x]补，右移 |
| 1 | 1 | 部分积右移 |

### 示例
[x]补=0.1011（+11），[y]补=1.0111（-9）

预期结果：11×(-9) = -99

按Booth算法逐步计算（略），最终得到结果补码。

## 补码乘法优势

1. **符号自动处理**：无需单独判断
2. **统一运算**：补码表示一致
3. **适合硬件**：与加减法电路配合

## 缺点

1. **算法复杂**：比原码乘法难
2. **可能需减法**：增加硬件

## Booth算法优势

- 乘数中连续1可合并处理（11→11只移位）
- 减少加法次数
- 适合有符号数

## 应用

- **现代CPU**：普遍采用Booth算法
- **硬件乘法器**
- **DSP**

## 扩展

- **Booth两位乘法**：每次处理2位，更快
- **华莱士树**：并行乘法

> 💡 补码乘法（Booth算法）是现代CPU乘法运算的基础`,
