    answer: `## Booth算法

**Booth算法**是比较高效的补码乘法算法，通过**乘数相邻两位比较**决定操作。

## 核心思想

观察乘数相邻两位（当前位yᵢ和低位yᵢ₋₁）的状态，决定加减被乘数或仅移位。

## Booth规则

设y₋₁=0（初始附加位），每次判断(yᵢ, yᵢ₋₁)：

| yᵢ | yᵢ₋₁ | 含义 | 操作 |
|----|------|------|------|
| 0 | 0 | 进入0串 | 部分积右移1位 |
| 0 | 1 | 0串结束 | +[x]补，右移 |
| 1 | 0 | 1串开始 | -[x]补，右移 |
| 1 | 1 | 1串中 | 部分积右移 |

## 算法步骤

1. 设部分积P=0，附加位y₋₁=0
2. 循环n次：
   a. 判断(y₀, y₋₁)
   b. 按规则加减[x]补
   c. 部分积和乘数一起**算术右移**
3. 最后一步不移位

## 示例

[x]补 = 1.0110（-10）
[y]补 = 1.0010（-14）

预期：(-10)×(-14) = 140

### 计算过程（4位）

附加位y₋₁=0，[-x]补=0.1010

| 步骤 | 操作 | 部分积 | 乘数 | y₋₁ |
|------|------|--------|------|------|
| 初值 | - | 00.0000 | 10010 | 0 |
| 1 | (0,0)移位 | 00.0000 | 01001 | 0 |
| 2 | (1,0)-x | 11.1010 | 01001 | 0 |
| | 移位 | 11.1101 | 00100 | 1 |
| 3 | (0,1)+x | 00.0111 | 00100 | 1 |
| | 移位 | 00.0011 | 10010 | 0 |
| 4 | (1,0)-x | 11.1101 | 10010 | 0 |
| | 移位 | 11.1110 | 01001 | 1 |

结果：11.1110 0100 1（补码）

取数值部分并转换：0.10001100 = 140/256 × 256 = 140 ✓

## Booth算法优势

1. **符号位参与**：正负数统一处理
2. **减少加法**：连续1只需首尾加减
3. **速度快**：乘数中1越多越快

## 两位Booth算法

每次处理2位乘数，进一步减少循环次数：

| yᵢ₊₁yᵢyᵢ₋₁ | 操作 |
|-----------|------|
| 000 | 移2位 |
| 001 | +x，移2位 |
| 010 | +x，移2位 |
| 011 | +2x，移2位 |
| 100 | -2x，移2位 |
| 101 | -x，移2位 |
| 110 | -x，移2位 |
| 111 | 移2位 |

## 应用

- **现代CPU乘法器**
- **DSP**
- **硬件实现**

## 注意

- Booth算法用于**补码**乘法
- 移位是**算术右移**（保持符号位）
- 最后一步不移位

> 💡 Booth算法是补码乘法的经典算法，现代CPU广泛采用`,
