    answer: `## DRAM刷新方式

电容电荷易泄漏，需定期刷新（读出+重写），常用刷新周期2ms。

## 1. 集中刷新

- 在刷新周期末尾**集中**刷新所有行
- **优点**：存取速度快（正常读写不受影响）
- **缺点**：有较长的"死时间"（死区），期间不能读写

## 2. 分散刷新

- 每个存取周期分两段：前半读写，后半刷新一行
- **优点**：无死区
- **缺点**：存取周期变长（翻倍），系统速度降低

## 3. 异步刷新

- 每隔**刷新周期/行数**时间刷新一行
- 例：2ms内刷新128行，每15.6μs刷新一行
- **优点**：死时间最短（每次仅一行的时间）
- **缺点**：控制较复杂

## 对比

| 方式 | 死时间 | 速度 | 复杂度 |
|------|--------|------|--------|
| 集中 | 长 | 快 | 低 |
| 分散 | 无 | 慢 | 低 |
| 异步 | 最短 | 较快 | 中 |

> 💡 现代DRAM多采用异步刷新，兼顾速度与死时间`,
