    answer: `## ROM（只读存储器）分类

| 类型 | 写入方式 | 是否可改写 | 用途 |
|------|----------|-----------|------|
| 掩膜ROM | 出厂写入 | 不可 | 大批量固件 |
| PROM | 用户熔丝写入 | 一次 | 小批量固件 |
| EPROM | 紫外线擦除 | 多次 | 开发调试 |
| EEPROM | 电擦除 | 多次 | 配置参数 |
| Flash | 电擦除(块) | 多次 | U盘/SSD |

## 各类特点

### 1. 掩膜ROM
- 厂家掩膜工艺写入，**永久不可改**
- 成本低，适合大批量生产

### 2. PROM（可编程ROM）
- 用户用专用写入器熔断熔丝编程
- **只能写一次**

### 3. EPROM（可擦除PROM）
- 紫外线照射擦除（需取出芯片）
- 整片擦除，擦写次数有限

### 4. EEPROM（电可擦除）
- 电信号擦除，**可在线修改**
- 按字节擦写，但速度慢

### 5. Flash（闪存）
- 按块擦除，速度快
- **NOR Flash**：随机读取，存代码
- **NAND Flash**：顺序读取，存数据（SSD/U盘）

> 💡 Flash是当前最常用的非易失存储介质`,
