    question: '多体交叉存储器的工作原理是什么？',
    answer: `## 多体交叉存储器

将主存分为多个**存储体**，每个体可独立读写，**并行工作**提高带宽。

## 组织方式

### 1. 高位交叉编址
- **高位地址**选择存储体，低位地址选体内单元
- 相邻地址在同一存储体内
- **特点**：利于扩充容量，但不利于并行（顺序访问无并行）

### 2. 低位交叉编址
- **低位地址**选择存储体，高位地址选体内单元
- 相邻地址在不同存储体内
- **特点**：利于并行存取，提高带宽

## 低位交叉工作过程

设有m个体，存取周期T：

1. CPU给出地址，低位选中某个体
2. 每隔**T/m**时间启动一个体的存取
3. m个体流水线式工作

## 性能分析

- **理想情况**：带宽提升m倍
- **前提**：连续访问的地址在不同体中
- **体数**：m ≥ T/τ（τ为总线周期）

## 举例

- 4个体，存取周期400ns，总线周期100ns
- 每隔100ns启动一个体
- 4个体流水，等效存取周期降为100ns

> 💡 低位交叉编址让连续地址访问并行化，大幅提升带宽`,
