    keyword: '写策略',
    question: 'Cache的写策略有哪几种？',
    answer: `## Cache写策略

CPU写Cache时，如何保持Cache与主存数据**一致**。

## 两大类策略

### 1. 全写法（Write-Through）

- 写命中时，**同时写Cache和主存**
- 数据即时一致

### 2. 写回法（Write-Back）

- 写命中时，**只写Cache**
- 被替换时才写回主存
- 用**脏位（修改位）**标记是否修改过

## 写缺失时的策略

### 1. 写分配（Write-Allocate）
- 写缺失时，先从主存调入Cache，再写Cache
- 配合写回法使用

### 2. 非写分配（No-Write-Allocate）
- 写缺失时，直接写主存，不调入Cache
- 配合全写法使用

## 常见组合

| 写命中 | 写缺失 | 特点 |
|--------|--------|------|
| 全写法 + 非写分配 | 直接写主存 | 简单，一致性好，慢 |
| 写回法 + 写分配 | 调入再写 | 快，复杂，需脏位 |

## 选择依据

- **全写法**：数据一致性好，但写慢，总线繁忙
- **写回法**：写快，但一致性复杂，替换时需写回

> 💡 写回法+写分配是高性能Cache的主流选择`,
