    question: '全写法（Write-Through）的原理和特点？',
    answer: `## 全写法（Write-Through）

写命中时，**同时写Cache和主存**，保持数据即时一致。

## 工作过程

### 写命中
1. 数据写入Cache
2. **同时**写入主存
3. 主存与Cache始终一致

### 写缺失
- 通常配合**非写分配**：直接写主存，不调入Cache

## 优点

- **数据一致性好**：Cache与主存随时一致
- **实现简单**：无需脏位
- **替换简单**：替换时无需写回（主存已是最新）

## 缺点

- **写速度慢**：每次写都要访问主存
- **总线繁忙**：写操作占用总线带宽
- **功耗高**

## 优化：写缓冲（Write Buffer）

- 用**写缓冲队列**暂存写主存的请求
- CPU写Cache后立即返回，主存写操作异步进行
- 减轻写延迟，但缓冲满时仍需等待

## 适用场景

- 对数据一致性要求高的场合
- 多处理器系统（简化一致性协议）

> 💡 全写法靠写缓冲缓解慢速写，适合简单系统`,
