    question: '脏位（修改位）的作用是什么？',
    answer: `## 脏位（Dirty Bit）

标记Cache行是否被**修改**过（与主存不一致）。

## 作用

- 配合**写回法**使用
- 决定替换时是否需要写回主存

## 工作规则

### 写入时
- 修改Cache行数据
- **置脏位 = 1**

### 替换时
- 脏位 = 0：该行未修改，与主存一致 → **直接替换**，无需写回
- 脏位 = 1：该行已修改 → **先写回主存**，再替换

### 调入时
- 从主存调入新块
- **置脏位 = 0**

## 优点

- **减少写主存次数**：只有修改过的行才写回
- **降低总线负载**

## 与有效位的区别

| 位 | 含义 |
|----|------|
| 有效位 | 该行是否有有效数据 |
| 脏位 | 该行是否被修改过（主存是否过期） |

## 状态组合

| 有效位 | 脏位 | 状态 |
|--------|------|------|
| 0 | 0 | 空（无数据） |
| 1 | 0 | 有效且干净（与主存一致） |
| 1 | 1 | 有效且脏（已修改） |

> 💡 脏位让写回法只在必要时写回主存，大幅减少写主存开销`,
