    keyword: '缺页',
    question: '缺页中断的处理过程是怎样的？',
    answer: `## 缺页（Page Fault）

访问的页面**不在主存**中（页表有效位=0），需从辅存调入。

## 缺页处理过程

1. **CPU访存**，地址变换查页表
2. 发现有效位=0 → **触发缺页中断**
3. **切换到内核态**，执行缺页处理程序
4. 查**外页表**找到该页在辅存的位置
5. 从辅存读取页面到主存：
   - 主存有空闲页框 → 直接调入
   - 主存已满 → 调用**页面替换算法**选一页换出
     - 若换出页脏位=1 → 写回辅存
6. **更新页表**：实页号、有效位=1
7. 更新TLB
8. **重新执行**引起缺页的指令

## 页面替换算法

| 算法 | 原理 | 特点 |
|------|------|------|
| OPT | 换最长时间不用的页 | 理想，不可实现 |
| FIFO | 换最早调入的页 | 简单，有Belady异常 |
| LRU | 换最久未访问的页 | 常用，近似OPT |
| Clock | 访问位轮转 | LRU近似，开销小 |

## 缺页代价

- 辅存访问（磁盘）约毫秒级
- 比主存访问慢10⁵~10⁶倍
- 缺页率应极低（<10⁻⁵）

## 与TLB缺失区别

| 特性 | TLB缺失 | 缺页 |
|------|--------|------|
| 页在主存？ | 在 | 不在 |
| 处理 | 查页表 | 调入页面 |
| 代价 | 小（几次访存） | 大（磁盘I/O） |
| 频率 | 较高 | 极低 |

> 💡 缺页中断是虚拟存储器"按需调页"的核心机制`,
