    id: 'q172',
    keyword: 'Clock算法',
    question: 'Clock（时钟）页面替换算法的工作过程？',
    answer: `## Clock算法

LRU的低开销近似实现，用**访问位**模拟近期访问情况。

## 基本原理

- 所有页在内存中组成**循环队列**
- 一个指针指向当前位置
- 每页有一个**访问位**：
  - 被访问时置1
  - 替换时扫描

## 工作过程

1. 需替换时，指针从当前位置开始扫描
2. 若当前页**访问位=1**：
   - 置为0（给第二次机会）
   - 指针前进
3. 若当前页**访问位=0**：
   - **替换该页**
   - 指针前进到下一页

## 举例

| 页 | 访问位 |
|----|--------|
| A  | 1→0 |
| B  | 1→0 |
| C  | 0 → 替换 |

指针从A开始：A置0→B置0→C替换

## 改进型Clock（考虑修改位）

按 (访问位A, 修改位M) 优先级：

1. **第一轮**：找 (0,0) 的页替换
2. **第二轮**：找 (0,*) 的页，并将A置0
3. **第三轮**：找 (0,0) 的页
4. **第四轮**：找 (0,*) 的页

- 优先替换干净页（M=0），减少写回

## 优点

- **开销小**：只需1位（基本Clock）
- **性能接近LRU**
- 无需精确时间记录

> 💡 Clock算法又称"第二次机会"算法，是实用系统的首选`,
    relatedTopics: ['页面替换', 'LRU', '访问位'],
    chapter: '第3章 存储系统',
    difficulty: 'advanced',
