    question: '存储层次中的数据一致性问题如何保证？',
    answer: `## 数据一致性问题

多级存储中，同一数据的**多个副本**可能不一致。

## 一致性问题来源

1. **Cache-主存**：写回法下Cache与主存暂时不一致
2. **多核Cache**：各核Cache中同一数据的副本
3. **主存-辅存**：虚拟存储中页面修改未写回

## Cache-主存一致性

| 写策略 | 一致性保证 |
|--------|-----------|
| 全写法 | 始终一致 |
| 写回法 | 替换时写回（用脏位管理） |

## 多核Cache一致性

### 写更新（Write-Update）
- 写入时**更新**所有Cache中的副本
- 带宽消耗大

### 写无效（Write-Invalidate）
- 写入时使其他Cache中的副本**失效**
- 带宽消耗小，**主流方案**

## 总线监听协议

- 各Cache监听总线上的写操作
- 监听到对自己副本的写 → 失效或更新

## 目录协议

- 用目录记录每块数据的Cache位置
- 适合大规模多核（非总线）
- 减少广播开销

## 一致性模型

- **顺序一致性**：所有操作按某全局顺序执行
- **释放一致性**：仅在同步点保证一致
- **弱一致性**：普通访问不需同步

> 💡 写无效+总线监听是中小规模多核的主流一致性方案`,
