    question: '写更新和写无效两种一致性策略的区别？',
    answer: `## 两种Cache一致性策略

多核系统中，一个核修改数据后如何处理其他核Cache中的副本。

## 1. 写更新（Write-Update）

- 写入本核Cache时，**同时更新**所有其他Cache中的副本

### 过程
1. Core1修改数据X
2. 通过总线发送新值给所有持有X的Cache
3. 各Cache更新副本

### 特点
- **优点**：其他核立即可用新值
- **缺点**：写操作占用大量总线带宽
- 多次写同一数据 → 反复广播

## 2. 写无效（Write-Invalidate）

- 写入本核Cache时，**使其他Cache中的副本失效**

### 过程
1. Core1修改数据X
2. 通过总线发送无效信号
3. 其他Cache的X副本标记为无效
4. 其他核访问X时缺失，从Core1或主存取最新值

### 特点
- **优点**：带宽消耗小（只发无效信号）
- **优点**：多次写同一数据只发一次无效
- **缺点**：其他核首次访问需缺失处理

## 对比

| 特性 | 写更新 | 写无效 |
|------|--------|--------|
| 通信量 | 大 | 小 |
| 写后读延迟 | 低 | 较高 |
| 实现复杂度 | 中 | 中 |
| 商用采用 | Dragon协议 | MESI（主流） |

## 选择

- 写无效是**主流方案**（MESI协议）
- 适合写后较少立即读的场景

> 💡 现代多核CPU普遍采用写无效策略`,
