    keyword: '内存保护',
    question: '虚拟存储器如何实现内存保护？',
    answer: `## 内存保护机制

防止进程越权访问其他进程或操作系统的内存。

## 保护方式

### 1. 地址空间隔离
- 每个进程有独立的**虚拟地址空间**
- 通过页表映射到不同物理页
- 进程A的虚拟地址映射不到进程B的物理页

### 2. 访问权限控制
页表项中有**保护位**：

| 权限位 | 含义 |
|--------|------|
| 读(R) | 是否可读 |
| 写(W) | 是否可写 |
| 执行(X) | 是否可执行 |
| 用户/内核(U/S) | 用户态是否可访问 |

### 3. 特权级保护
- 内核态（特权级0）可访问所有内存
- 用户态（特权级3）只能访问用户空间
- 越权访问触发**段错误/访问违例**

## 地址变换中的检查

1. 地址变换时检查页表项权限
2. 虚拟地址有效位=0 → 缺页
3. 权限不符 → **访问违例异常**
4. 越界访问 → **段错误**

## 举例

- 进程A页表映射物理页10~20
- 进程B页表映射物理页30~40
- A无法访问B的物理页（页表中没有映射）

## 越界检查

- 段式管理：检查偏移 < 段长
- 页式管理：页表项存在性即保护

> 💡 虚拟存储器天然提供进程间隔离，是系统安全的基石`,
