    keyword: '性能优化',
    question: '存储系统有哪些性能优化技术？',
    answer: `## 存储系统性能优化

## 一、Cache层面

### 1. 增大相联度
- 组相联替代直接映射，减少冲突缺失

### 2. 多级Cache
- L1求速度，L2/L3求命中率

### 3. 分离Cache
- 指令/数据分离，消除结构冲突

### 4. 牺牲Cache（Victim Cache）
- 在L1和L2间加小全相联Cache
- 缓存被替换的块，减少冲突缺失

### 5. 预取（Prefetch）
- 基于空间局部性，提前取数据
- 硬件预取 / 软件预取

## 二、主存层面

### 1. 多体交叉
- 低位交叉编址，并行存取提高带宽

### 2. 猝发传输
- 一次地址传多个连续数据

### 3. DDR技术
- 时钟上下沿都传数据（DDR/DDR2/DDR3/DDR4）

## 三、虚拟存储层面

### 1. TLB优化
- 增大TLB容量，提高命中率
- ASID减少进程切换刷新

### 2. 大页（Huge Page）
- 2MB/1GB大页减少页表项数
- 降低TLB缺失

### 3. 写时复制（COW）
- fork时共享页面，写时才复制

## 四、综合

- **非易失内存**（NVM）：模糊存储层次
- **堆叠内存**（HBM）：增大带宽
- **压缩内存**：减少访存数据量

> 💡 多级Cache+多体交叉+TLB是存储性能的三大支柱`,
